-- ROOM_LENS_VISUAL_HIGHLIGHT_SPEC.md sec21/22: mesh-derived walkable raster, built AFTER
-- applying this file's own spatial_structure patch (105 real rooms, not the raw db's 23) --
-- see build command in buildings/patches/README.md. Proven 33.7%->28.7% DETOUR_FAIL-rate drop
-- on the TRUE production room set (5460-pair sweep). An EARLIER raster (built pre-2026-07-15
-- against the raw unpatched 23-room db) regressed this same metric to 40.5% when combined with
-- the spatial_structure patch -- do not reintroduce that version.
CREATE TABLE IF NOT EXISTS storey_walkable_raster (storey TEXT PRIMARY KEY, res REAL, x0 REAL, y0 REAL, cols INTEGER, rows INTEGER, bits BLOB);
