-- §NOGEO_COMPOSE (2026-08-10): real IfcRelAggregates parent->child pairs for
-- HHS_Office_Federated's 41 guid-only elements (no own Representation -- 33 IfcCurtainWall +
-- 8 IfcStair containers whose geometry lives entirely on these children, same class as the
-- Hospital/Duplex gap). No computed values here -- the composition itself runs client-side at
-- load time (scene.js composeGhostsFromAggregates, ported from import_worker.js's
-- §4D_NOGEO_COMPOSE) from this relationship data plus the children's OWN already-shipped,
-- already-real element_transforms rows. Source: internal/UNMERGED/opensourceBIM_HHS_Office_
-- architect.ifc (33 curtain walls) + opensourceBIM_HHS_Office_construction.ifc (8 stairs) --
-- HHS_Office_Federated.ifc merge-source is federated from these + MEP disciplines, confirmed
-- these 41 parent GUIDs resolve identically in the per-discipline IFCs. See
-- prompts/4D_SCHEDULE_PERFECTION.md 2026-08-10 entry.
CREATE TABLE IF NOT EXISTS rel_aggregates (parent_guid TEXT NOT NULL, child_guid TEXT NOT NULL, PRIMARY KEY (parent_guid, child_guid));
